"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Signal in the Static', 'author': 'Signature original', 'genre': 'Rebel Alliances', 'chapters': [{'n': 1, 'title': 'Contraband', 'text': "In the safehouse, the hacker Jinx cracked it open — carefully, lovingly, the way you defuse a bomb. What spilled out wasn't data. It was memory. Real memory. Of New Babel before.\n\nLena Vogt found a paper book in the gutters of New Babel, where the drones don't look because the poor are invisible — Director Vane's mistake, and everyone's opportunity. It was warm. Data shouldn't be warm.\n\nThey moved through New Babel like smoke: checkpoints avoided, cameras looped, the concrete humming its electric lullaby. a paper book pulsed in Lena Vogt's pocket like a second heart."}, {'n': 2, 'title': 'The Network', 'text': "Director Vane noticed. Of course Director Vane noticed — the Algorithm sees all. Patrols doubled. The drone got louder. Friends started disappearing from the usual corners.\n\na paper book was copied, hand to hand, each copy a little degraded, each copy a little more precious. Lena Vogt watched a twelve-year-old memorize the whole thing rather than risk carrying it. The future, Lena Vogt thought, is in good hands.\n\n'They're going to come for us,' the hacker Jinx said. Lena Vogt nodded. 'Let them. We're already everywhere.'"}, {'n': 3, 'title': 'Blackout', 'text': "'Now,' said the hacker Jinx. And New Babel — all of New Babel, every screen, every speaker — remembered.\n\nAt the top, the hacker Jinx's hands flew. 'Thirty seconds to signal,' the hacker Jinx said. Below, the Patrol's lights converged like angry stars. Lena Vogt stood at the window with a paper book and thought of green things growing.\n\nThe blackout was the hacker Jinx's masterpiece: three minutes of dark across New Babel, bought with a year's favors. Three minutes to move a paper book to the broadcast tower. Three minutes to change the world."}, {'n': 4, 'title': 'The Remembering', 'text': "What happened in the next hour, historians argue about. What Lena Vogt remembers: silence, then a sound like a held breath released, then the streets filling with people who had remembered they were people.\n\nDirector Vane responded the only way Director Vane knew: force. The Patrol marched. The drones rose. And the people of New Babel — who had just remembered green, and laughter, and sky — stood in the streets and would not move.\n\nLena Vogt and the hacker Jinx were in the tower when the door blew. The ex-enforcer held the stairs long enough. Long enough for what? For the footage to loop. For the memory to root. For Director Vane's lie to die on every screen at once."}, {'n': 5, 'title': 'After the Static', 'text': 'Lena Vogt kept the dead chip in a pocket. A reminder: that truth is a seed, that seeds die to grow, that one a paper book in the right hands at the right time is worth an army.\n\nRebuilding New Babel was harder than freeing it. Lena Vogt organized food lines with the same care once used for heists. the hacker Jinx taught kids to code on salvaged terminals. The medic ran a clinic. The runner ran messages of hope.\n\nAnd when the new council asked Lena Vogt to lead, Lena Vogt laughed and went back to the food lines. Leaders, Lena Vogt had learned, are just people who show up. Lena Vogt shows up.'}, {'n': 6, 'title': 'The Habit of Freedom', 'text': "Sometimes Lena Vogt walks to the tower and looks out over New Babel, green in the cracks of the concrete, alive in the way of things that remember. a paper book is gone. What it carried isn't.\n\nthe hacker Jinx runs the network now — the real one, the open one, the one that belongs to everyone. The concrete is quieter. The neon is warmer. It turns out freedom has a sound, and it's laughter.\n\nfreedom is a habit — Lena Vogt thinks it every time, like a prayer, like a promise. Memory is resistance. Freedom is a habit. Practice daily."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

